const D = { n:5, energy:.65, hue:200, speed:1, density:.5, scale:1, x:.5, y:.13, seed:0, style:'rig', act:'concert', haze:.6, spread:.6 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q=Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q-Math.floor(q); };
const lp=(a,b,t)=>a+(b-a)*t;
const TAU=Math.PI*2;
const W=width, Hh=height, u=Math.min(W,Hh);
const H=((P.hue%360)+360)%360;
const styles=['rig','wireframe','neon','noir','riso'];
const st=styles.includes(P.style)?P.style:'rig';
const n=Math.max(2,Math.min(8,Math.round(P.n)));
const spd=P.speed;
const dens=Math.max(.2,Math.min(1,P.density));
const trussY=P.y*Hh;

// per-section color schemes (cues advance with the musical arc)
const schemes=[[H,90,100],[(H+45)%360,88,100],[(H+180)%360,86,100],[(H+300)%360,90,100],[52,20,100]];
const sec=Math.floor(K.section)%schemes.length;
const beamC = st==='noir'? [0,0,100] : (st==='riso'? [186,80,96] : schemes[sec]);
const beamC2 = st==='riso'? [9,84,96] : schemes[(sec+2)%schemes.length];

// act shaping (multi-minute dramaturgy)
let sweepAmp=0.55*P.spread, rate=1, parFlash=1;
if(P.act==='ballad'){ sweepAmp=0.28*P.spread; rate=0.5; parFlash=0.6; }
else if(P.act==='strobe'){ sweepAmp=0.85*P.spread; rate=1.8; parFlash=1.6; }

// ── truss structure cached (static lattice) ──
const key=W+'x'+Hh+'|'+st+'|'+P.seed+'|'+Math.round(trussY)+'|'+P.scale;
if(S.truss==null || S.tKey!==key){
  const g=createGraphics(W,Math.max(2,Math.round(trussY+u*0.12))); g.colorMode(g.HSB,360,100,100,100);
  const th=u*0.055*P.scale;               // truss height
  const y0=trussY-th/2, y1=trussY+th/2;
  const mCol = st==='wireframe'?[200,70,96]:(st==='neon'?[H,40,60]:(st==='riso'?[46,10,70]:[0,0,32]));
  const mDark = st==='wireframe'?[200,60,60]:(st==='riso'?[46,10,50]:[0,0,18]);
  g.stroke(mCol[0],mCol[1],mCol[2]); g.strokeWeight(Math.max(1.5,u*0.004*P.scale));
  // top & bottom chords
  g.line(0,y0,W,y0); g.line(0,y1,W,y1);
  // diagonal lattice web
  g.strokeWeight(Math.max(1,u*0.0025*P.scale));
  const seg=u*0.05*P.scale;
  for(let x=0;x<W;x+=seg){ g.line(x,y0,x+seg,y1); g.line(x+seg,y0,x,y1); }
  // vertical posts
  g.stroke(mDark[0],mDark[1],mDark[2]); for(let x=0;x<=W;x+=seg*2){ g.line(x,y0,x,y1); }
  if(st!=='wireframe'){ // hang points / motors
    g.noStroke(); g.fill(mDark[0],mDark[1],mDark[2]);
    for(let x=seg; x<W; x+=seg*2){ g.rect(x-u*0.006,y0-u*0.02*P.scale,u*0.012,u*0.02*P.scale); }
  }
  S.truss=g; S.tKey=key;
}

// ── moving-head beams (continuous pan = real-time motion floor) ──
const hazeA = P.haze*(0.6+0.4*K.intensity);
const eLen = 0.55+P.energy*0.6;   // beam length fraction of height
blendMode(ADD); noStroke();
const bassG=(A.bass||0);
for(let i=0;i<n;i++){
  const ox = lp(W*0.08,W*0.92,n===1?0.5:i/(n-1));
  const oy = trussY+u*0.03*P.scale;
  const phase=fr(i*7)*TAU;
  const dirSign=(i%2===0)?1:-1;
  // pan: continuous sine drift (never re-phases) + slow section wander
  const pan = Math.sin(K.t*0.6*rate*spd*dirSign+phase)*sweepAmp
            + Math.sin(K.t*0.13*spd+phase)*0.18;
  const ang = Math.PI/2 + pan;
  const L = Hh*eLen*(0.75+0.25*Math.sin(K.t*1.3+phase));
  const dx=Math.cos(ang), dy=Math.sin(ang), px=-dy, py=dx;
  const wTop=u*0.008*P.scale, wBot=u*0.075*P.scale*(0.7+P.energy*0.6);
  const tipx=ox+dx*L, tipy=oy+dy*L;
  // beam intensity: clk baseline + audio on top
  const inten = (0.55+0.45*Math.sin(K.t*1.1+phase)) * (0.7+0.3*K.swell) + bassG*0.5;
  const cc = (i%2===0)?beamC:beamC2;
  // volumetric cone (few translucent layers, ADD alpha <=35)
  for(let lyr=0;lyr<3;lyr++){ const wt=wBot*(0.4+lyr*0.35); const a=(9-lyr*2.5)*hazeA*inten;
    fill(cc[0],cc[1],cc[2],a); quad(ox+px*wTop,oy+py*wTop, ox-px*wTop,oy-py*wTop, tipx-px*wt,tipy-py*wt, tipx+px*wt,tipy+py*wt); }
  // bright core
  fill(cc[0],Math.max(0,cc[1]-40),100, 22*inten); quad(ox+px*wTop*0.5,oy+py*wTop*0.5, ox-px*wTop*0.5,oy-py*wTop*0.5, tipx-px*wBot*0.25,tipy-py*wBot*0.25, tipx+px*wBot*0.25,tipy+py*wBot*0.25);
  // ground pool where beam lands
  fill(cc[0],cc[1],100, 16*inten); ellipse(tipx,tipy,wBot*1.6,wBot*0.5);
  // fixture head hotspot
  fill(cc[0],40,100, 40*inten); ellipse(ox,oy,u*0.02*P.scale,u*0.02*P.scale);
}
blendMode(BLEND);

// moving-head yoke bodies (drawn over truss)
for(let i=0;i<n;i++){
  const ox = lp(W*0.08,W*0.92,n===1?0.5:i/(n-1));
  const oy = trussY+u*0.03*P.scale;
  const phase=fr(i*7)*TAU;
  const dirSign=(i%2===0)?1:-1;
  const pan = Math.sin(K.t*0.6*rate*spd*dirSign+phase)*sweepAmp+Math.sin(K.t*0.13*spd+phase)*0.18;
  push(); translate(ox,oy);
  if(st==='wireframe'){ noFill(); stroke(200,70,96,90); strokeWeight(1.3); rect(-u*0.014*P.scale,-u*0.02*P.scale,u*0.028*P.scale,u*0.03*P.scale); rotate(pan*0.5); rect(-u*0.008*P.scale,0,u*0.016*P.scale,u*0.026*P.scale); }
  else { noStroke(); fill(0,0,14); rect(-u*0.016*P.scale,-u*0.022*P.scale,u*0.032*P.scale,u*0.03*P.scale,u*0.004); fill(0,0,22); rect(-u*0.012*P.scale,-u*0.024*P.scale,u*0.024*P.scale,u*0.008*P.scale); rotate(pan*0.5); fill(0,0,9); rect(-u*0.009*P.scale,0,u*0.018*P.scale,u*0.026*P.scale,u*0.003); }
  pop();
}

image(S.truss,0,0);

// ── PAR cans: static downlights flashing on the beat ──
const nPar=Math.round(lp(3,9,dens));
blendMode(ADD); noStroke();
for(let i=0;i<nPar;i++){
  const px2=lp(W*0.06,W*0.94,nPar===1?0.5:i/(nPar-1));
  const py2=trussY+u*0.04*P.scale;
  const beat4=Math.floor(K.beat)%4;
  const on = (i%4)===beat4;
  const fl = (on? 1: 0.12) * K.pulse*parFlash + 0.08;
  const pc = schemes[(sec+i)%schemes.length];
  const cc = st==='noir'?[0,0,100]:(st==='riso'?(i%2?[9,84,96]:[186,80,96]):pc);
  const L=Hh*0.45*(0.6+fl*0.8);
  fill(cc[0],cc[1],cc[2], 10*fl);
  quad(px2-u*0.006,py2, px2+u*0.006,py2, px2+u*0.05*P.scale,py2+L, px2-u*0.05*P.scale,py2+L);
  fill(cc[0],cc[1],100, 30*fl); ellipse(px2,py2,u*0.016*P.scale,u*0.016*P.scale);
}
blendMode(BLEND);
// PAR can bodies
for(let i=0;i<nPar;i++){ const px2=lp(W*0.06,W*0.94,nPar===1?0.5:i/(nPar-1)); const py2=trussY+u*0.028*P.scale; noStroke(); fill(0,0, st==='wireframe'?0:12); if(st==='wireframe'){ stroke(200,70,90,80); strokeWeight(1); noFill(); } ellipse(px2,py2,u*0.02*P.scale,u*0.014*P.scale); }

blendMode(BLEND);
drawingContext.shadowBlur=0;
